  dt.id AS `dt.id`,
  12 * (
    YEAR(dt.d2) - YEAR(dt.d1)
  ) + (
    MONTH(dt.d2) - MONTH(dt.d1)
  ) AS `dt.v`
FROM dt AS dt
GROUP BY
  dt.id,
  12 * (
